-- Kaynak: Depolar-Subeler.xlsx / Ruhsatlı Depolar!A2:F586
-- İlk katalog yüklemesi: 326 depo adı, 585 depo/şube konumu.
-- UUID'ler uygulama içi kimliktir; resmi ruhsat numarası değildir.
-- Boş şube adları NULL kalır. Kaynak sıra numarası kalıcı kimlik değildir.
-- Aynı dosyanın tekrar çalıştırılması mükerrer kayıt üretmez.
-- Gelecekteki listeler, kimlik eşleştirmesi incelenmeden bu yöntemle üretilmemeli.
BEGIN;
SELECT pg_advisory_xact_lock(hashtextextended('hapbilgi-ecza-depo-katalogu-20260929', 0));

ON CONFLICT (depo_id) DO UPDATE SET depo_adi = EXCLUDED.depo_adi;

ON CONFLICT (depo_sube_id) DO UPDATE SET
  depo_id = EXCLUDED.depo_id,
  sube_adi = EXCLUDED.sube_adi,
  il = EXCLUDED.il,
  ilce = EXCLUDED.ilce,
  adres = EXCLUDED.adres,
  kaynak_sira_no = EXCLUDED.kaynak_sira_no,
  kaynak_dosya = EXCLUDED.kaynak_dosya;

DO $kontrol$
BEGIN
  IF (SELECT count(*) FROM public.ecza_depo_subeleri
      WHERE kaynak_dosya = 'Depolar-Subeler.xlsx') <> 585 THEN
    RAISE EXCEPTION 'Kaynak dosya kayıt sayısı 585 değil; yükleme geri alındı.';
  END IF;
END $kontrol$;
COMMIT;

SELECT count(*) AS yuklenen_konum,
       count(DISTINCT depo_id) AS depo_adi_sayisi,
       count(DISTINCT il) AS il_sayisi,
       count(*) FILTER (WHERE sube_adi IS NULL) AS sube_adi_bos
FROM public.ecza_depo_subeleri WHERE kaynak_dosya = 'Depolar-Subeler.xlsx';
